// TypeScript entry point for the Rust engines compiled to WebAssembly.
// `pkg/` is generated by `pnpm build:wasm`; never edit it by hand.
import init, { SheetsDocument, debugPanic, installPanicHook } from "../pkg/office_wasm.js";

export { SheetsDocument };

/** Must resolve before any engine class is used. Safe to call more than once. */
let ready: Promise<unknown> | undefined;
export function loadEngine(): Promise<unknown> {
  ready ??= init().then((exports) => {
    installPanicHook(reportPanic);
    return exports;
  });
  return ready;
}

// ---- crashes

type PanicListener = (message: string) => void;
const panicListeners = new Set<PanicListener>();
let lastPanic: string | null = null;

function reportPanic(message: string) {
  lastPanic = message;
  for (const listener of panicListeners) listener(message);
}

/**
 * Called with the panic message if the engine crashes. After a crash every
 * engine call may throw, so the UI should stop and offer a reload.
 * Returns an unsubscribe function.
 */
export function onEnginePanic(listener: PanicListener): () => void {
  panicListeners.add(listener);
  if (lastPanic !== null) listener(lastPanic);
  return () => panicListeners.delete(listener);
}

/** True for errors that mean the WebAssembly engine is no longer usable. */
export function isEngineCrash(error: unknown): boolean {
  if (typeof WebAssembly !== "undefined" && error instanceof WebAssembly.RuntimeError) return true;
  const message = error instanceof Error ? error.message : String(error);
  return lastPanic !== null || /recursive use of an object detected|null pointer passed to rust|unreachable/.test(message);
}

/** Make the engine panic, for testing the crash screen. */
export function triggerEnginePanicForTesting() {
  debugPanic();
}

/** Matches `kindBlock` in crates/wasm/src/lib.rs. */
export const ValueKind = {
  Empty: 0,
  Number: 1,
  Text: 2,
  Bool: 3,
  Error: 4,
} as const;

export type NumberFormatKind = "general" | "number" | "currency" | "percent" | "date" | "time" | "datetime" | "text" | "custom";

/** Matches `style_json` in crates/wasm/src/lib.rs. */
export interface CellStyle {
  b?: 1;
  i?: 1;
  u?: 1;
  s?: 1;
  color?: string;
  fill?: string;
  align?: "left" | "center" | "right";
  fmt?: NumberFormatKind;
  /** The Excel format code (present whenever `fmt` is). */
  code?: string;
  /** Font family; absent = the default (Calibri). */
  font?: string;
  /** Font size in points; absent = 11. */
  sz?: number;
  /** Wrap Text. */
  wrap?: 1;
  /** Vertical alignment; absent = bottom (Excel's default). */
  va?: "top" | "center";
  border?: CellBorders;
}

/** `.xlsx` border style names, as used by `applyBorders`. */
export type BorderStyleName =
  | "thin"
  | "medium"
  | "thick"
  | "dashed"
  | "dotted"
  | "double"
  | "hair"
  | "mediumDashed"
  | "dashDot"
  | "mediumDashDot"
  | "dashDotDot"
  | "mediumDashDotDot"
  | "slantDashDot";

export interface BorderLine {
  style: BorderStyleName;
  /** `#RRGGBB`; absent = automatic (black). */
  color?: string;
}

export interface CellBorders {
  top?: BorderLine;
  right?: BorderLine;
  bottom?: BorderLine;
  left?: BorderLine;
}

const EMPTY_STYLE: CellStyle = Object.freeze({});
const styleCache = new Map<string, CellStyle>();

/** Parse a style string from `styleBlock`. Results are cached, so it's cheap per frame. */
export function parseStyle(json: string): CellStyle {
  if (!json) return EMPTY_STYLE;
  let s = styleCache.get(json);
  if (!s) {
    s = JSON.parse(json) as CellStyle;
    styleCache.set(json, s);
  }
  return s;
}

export interface FunctionInfo {
  name: string;
  syntax: string;
  summary: string;
}

let functions: FunctionInfo[] | undefined;

/** All built-in spreadsheet functions, alphabetical. */
export function functionList(): FunctionInfo[] {
  functions ??= SheetsDocument.functionList().map((line) => {
    const [name, syntax, summary] = line.split("\t");
    return { name, syntax, summary };
  });
  return functions;
}
